# Packages
library(tidyverse)
library(here)
library(targets)
library(gt)
library(gtExtras)
library(sf)
library(leaflet)
library(osdatahub)
library(tidymodels)
library(tidyclust)
library(skimr)

# Sources all R/*.R same as _targets.R
tar_source()       

# ggplot theme
set_theme(theme_minimal())
```
:::


The data frame with candidate variables for clustering is called `df_lsoa`. Notes on the production of `df_lsoa` are in [ETL page](etl.qmd).  


